<template>
<div :class="['office-page map-page',{'presentation-mode':presenting}]" v-loading="loading">
  <header class="office-toolbar"><div class="office-actions map-heading"><el-button circle title="返回导图列表" @click="router.push('/mindmap')"><span class="material-symbols-outlined">arrow_back</span></el-button><h2>{{ title }}</h2><span class="office-muted">{{ saving?'保存中':canEdit?'已保存':'只读' }}</span></div><div class="office-actions"><el-select v-model="layout" aria-label="导图布局" :disabled="!canEdit||saving" @change="saveLayout"><el-option label="思维导图" value="mindmap"/><el-option label="组织架构图" value="org"/><el-option label="鱼骨图" value="fishbone"/></el-select><el-button circle title="操作历史" @click="openHistory"><span class="material-symbols-outlined">history</span></el-button><el-button circle title="保存为模板" :disabled="!canEdit" @click="capture"><span class="material-symbols-outlined">dashboard_customize</span></el-button><el-button circle title="导出图片或PDF" @click="exportOpen=true"><span class="material-symbols-outlined">download</span></el-button><el-button v-if="!presentation.active&&canEdit" @click="control('start')"><span class="material-symbols-outlined">present_to_all</span>演示</el-button><el-button v-if="presenting" @click="followPresentation=false">退出演示视图</el-button></div></header>
  <div class="map-tools" role="toolbar" aria-label="导图编辑工具"><el-button v-if="canEdit" circle title="添加子节点" :disabled="!selected||saving" @click="add(false)"><span class="material-symbols-outlined">add</span></el-button><el-button v-if="canEdit" circle title="添加同级节点" :disabled="!selected?.parentId||saving" @click="add(true)"><span class="material-symbols-outlined">add_to_photos</span></el-button><el-button circle title="节点属性" :disabled="!selected||saving" @click="edit"><span class="material-symbols-outlined">tune</span></el-button><el-button circle title="展开或折叠节点" :disabled="!selected?.children.length||!canEdit||saving" @click="collapse"><span class="material-symbols-outlined">{{ selected?.style.collapsed?'unfold_more':'unfold_less' }}</span></el-button><el-button v-if="canEdit" circle title="删除节点" :disabled="!selected?.parentId||saving" @click="remove"><span class="material-symbols-outlined">delete</span></el-button><span class="tool-divider"/><el-button circle title="缩小" :disabled="zoom<=.25" @click="zoom=Math.max(.25,zoom-.1)"><span class="material-symbols-outlined">zoom_out</span></el-button><span class="zoom-label">{{ Math.round(zoom*100) }}%</span><el-button circle title="放大" :disabled="zoom>=2" @click="zoom=Math.min(2,zoom+.1)"><span class="material-symbols-outlined">zoom_in</span></el-button><el-button circle title="适应画布" @click="fit"><span class="material-symbols-outlined">fit_screen</span></el-button><el-select v-model="follow" aria-label="跟随协作者视图" clearable placeholder="跟随视图"><el-option v-for="peer in livePeers" :key="peer.client" :value="peer.client" :label="peer.name"/></el-select></div>
  <div class="map-presence"><span :class="{online:connected}">{{ connected?'实时同步':'连接中' }}</span><span v-for="peer in livePeers" :key="peer.client">{{ peer.name }} · {{ peer.nodeName||'浏览中' }}</span><span>{{ activity }}</span></div>
  <el-alert v-if="error" :title="error" type="error" :closable="false"/>
  <div v-if="presentation.active" class="presentation-controls"><strong>{{ presentation.presenterName }} 正在演示</strong><span>{{ presentation.step+1 }}/{{ presentation.total }}</span><el-checkbox v-model="followPresentation">跟随演示</el-checkbox><template v-if="isPresenter"><el-button circle title="上一步" :disabled="presentation.step===0" @click="control('previous')"><span class="material-symbols-outlined">chevron_left</span></el-button><el-button circle title="下一步" :disabled="presentation.step>=presentation.total-1" @click="control('next')"><span class="material-symbols-outlined">chevron_right</span></el-button><el-button @click="annotate">标注</el-button><el-button @click="control('stop')">结束演示</el-button></template><p v-if="presentation.annotation">{{ presentation.annotation }}</p></div>
  <div ref="mapScroll" class="map-scroll" @scroll="broadcastView"><svg :width="geometry.width*zoom" :height="geometry.height*zoom" role="group" aria-label="思维导图"><g :transform="`scale(${zoom})`"><line v-if="layout==='fishbone'" x1="200" :y1="(geometry.nodes.find(n=>!n.parentId)?.y||0)+36" :x2="geometry.width-20" :y2="(geometry.nodes.find(n=>!n.parentId)?.y||0)+36" stroke="var(--c-text-muted)" stroke-width="2"/><path v-for="node in geometry.nodes.filter(n=>n.parentId)" :key="'edge'+node.id" :d="connector(node)" fill="none" :stroke="node.style.lineColor||'#a4b5cf'" :stroke-dasharray="node.style.lineStyle==='dashed'?'6 4':undefined" stroke-width="2"/><foreignObject v-for="node in geometry.nodes" :key="node.id" :x="node.x" :y="node.y" width="184" height="76"><div :class="['map-node-wrap',{selected:selectedId===node.id,peer:peerAt(node.id),current:presentation.active&&presentation.currentNodeId===node.id}]"><button :class="['map-node',{root:!node.parentId}]" :style="nodeStyle(node)" :aria-label="'节点 '+node.content" :title="[node.content,node.note,node.style.tag].filter(Boolean).join(' · ')" @pointerdown="dragStart($event,node)" @pointermove="dragMove" @pointerup="dragEnd" @pointercancel="cancelDrag" @click="selectNode(node)" @dblclick="selectNode(node);edit()" @keydown.enter.prevent="selectNode(node);edit()"><span v-if="node.icon" class="material-symbols-outlined node-icon">{{ node.icon }}</span><span class="node-text">{{ node.content }}</span><span v-if="node.style.tag" class="node-tag">{{ node.style.tag }}</span><span v-if="node.note" class="node-note" title="备注">•</span></button><button v-if="node.children.length" class="fold-node" :disabled="!canEdit||saving" :title="node.style.collapsed?'展开子节点':'折叠子节点'" @click.stop="selectedId=node.id;collapse()">{{ node.style.collapsed?'+'+node.children.length:'−' }}</button></div></foreignObject></g></svg></div>
  <footer class="map-detail" v-if="selected"><span>{{ selected.content }}</span><span class="office-muted">{{ allNodes.length }} 个节点 · {{ geometry.nodes.length }} 个可见</span><a v-if="selected.link" :href="selected.link" target="_blank" rel="noopener noreferrer">打开链接</a><span v-if="selected.note" class="node-remark">{{ selected.note }}</span></footer>
  <el-dialog v-model="editOpen" title="节点属性" width="520px" class="map-dialog"><el-form label-position="top"><el-form-item label="节点内容"><el-input v-model="draft.content" aria-label="节点内容" type="textarea" :rows="2" maxlength="500"/></el-form-item><el-form-item v-if="selected?.parentId" label="上级节点"><el-select v-model="draft.parentId" filterable aria-label="上级节点"><el-option v-for="node in availableParents" :key="node.id" :label="node.content" :value="node.id"/></el-select></el-form-item><div class="form-pair"><el-form-item label="文字颜色"><input v-model="draft.style.color" type="color" aria-label="节点文字颜色"/></el-form-item><el-form-item label="背景颜色"><input v-model="draft.style.background" type="color" aria-label="节点背景颜色"/></el-form-item><el-form-item label="边框颜色"><input v-model="draft.style.borderColor" type="color" aria-label="节点边框颜色"/></el-form-item><el-form-item label="连接线颜色"><input v-model="draft.style.lineColor" type="color" aria-label="连接线颜色"/></el-form-item><el-form-item label="字号"><el-input-number v-model="draft.style.fontSize" :min="10" :max="24"/></el-form-item><el-form-item label="字体"><el-select v-model="draft.style.fontFamily"><el-option v-for="font in ['Arial','Microsoft YaHei','SimSun','monospace']" :key="font" :value="font"/></el-select></el-form-item><el-form-item label="连接线"><el-select v-model="draft.style.connector"><el-option label="曲线" value="curve"/><el-option label="直线" value="straight"/><el-option label="折线" value="elbow"/></el-select></el-form-item><el-form-item label="线型"><el-select v-model="draft.style.lineStyle"><el-option label="实线" value="solid"/><el-option label="虚线" value="dashed"/></el-select></el-form-item></div><el-form-item label="图标"><el-radio-group v-model="draft.icon"><el-radio-button v-for="icon in ['', 'flag','star','check_circle','priority_high']" :key="icon" :value="icon"><span v-if="icon" class="material-symbols-outlined">{{ icon }}</span><span v-else>无</span></el-radio-button></el-radio-group></el-form-item><el-form-item label="标签"><el-input v-model="draft.style.tag" maxlength="50"/></el-form-item><el-form-item label="备注"><el-input v-model="draft.note" type="textarea" :rows="3" maxlength="4000"/></el-form-item><el-form-item label="链接"><el-input v-model="draft.link" placeholder="https://" maxlength="500"/></el-form-item></el-form><template #footer><el-button @click="editOpen=false">取消</el-button><el-button type="primary" :disabled="!canEdit" :loading="saving" @click="saveDraft">保存</el-button></template></el-dialog>
  <el-dialog v-model="historyOpen" title="操作历史（最近100次）" width="560px" class="map-dialog"><div v-for="item in history" :key="item.id" class="history-row"><div><strong>{{ item.label }}</strong><p class="office-muted">{{ item.createdAt }}</p></div><el-button :disabled="!canEdit||saving" @click="restore(item.id)">恢复</el-button></div><el-empty v-if="!history.length" description="暂无历史记录"/></el-dialog>
  <el-dialog v-model="exportOpen" title="导出导图" width="400px" class="map-dialog"><el-form label-position="top"><el-form-item label="文件格式"><el-radio-group v-model="exportType"><el-radio-button value="png">PNG 图片</el-radio-button><el-radio-button value="pdf">PDF</el-radio-button></el-radio-group></el-form-item></el-form><template #footer><el-button @click="exportOpen=false">取消</el-button><el-button type="primary" :loading="exporting" @click="exportMap">下载</el-button></template></el-dialog>
</div>
</template>
<script setup lang="ts">
import {computed,nextTick,onMounted,onBeforeUnmount,reactive,ref,watch} from 'vue'
import {useRoute,useRouter} from 'vue-router'
import {ElMessage,ElMessageBox} from 'element-plus'
import request from '@/utils/request'
import {getToken} from '@/utils/token'
import {wsClient} from '@/utils/wsClient'
import {flatten,layoutTree,type MapNode,type PlacedNode} from './geometry'
const route=useRoute(),router=useRouter(),id=String(route.params.docId),title=ref('思维导图'),root=ref<MapNode>(),selectedId=ref(''),canEdit=ref(false),loading=ref(false),saving=ref(false),error=ref(''),zoom=ref(1),layout=ref('mindmap'),mapScroll=ref<HTMLDivElement>(),editOpen=ref(false),historyOpen=ref(false),exportOpen=ref(false),exporting=ref(false),exportType=ref('png'),history=ref<any[]>([]),draft=reactive<any>({style:{}})
const allNodes=computed(()=>flatten(root.value)),selected=computed(()=>allNodes.value.find(n=>n.id===selectedId.value)),availableParents=computed(()=>allNodes.value.filter(n=>!new Set(flatten(selected.value).map(n=>n.id)).has(n.id))),previews=reactive<Record<string,{x:number;y:number}>>({}),presentation=reactive<any>({active:false,step:0,total:0}),followPresentation=ref(true),userId=ref(''),isPresenter=computed(()=>String(presentation.presenterId)===userId.value),presenting=computed(()=>presentation.active&&followPresentation.value)
const geometry=computed(()=>{const reveal=presenting.value?new Set(allNodes.value.slice(0,presentation.step+1).map(n=>n.id)):undefined;const result=layoutTree(root.value,layout.value,reveal);for(const node of result.nodes)if(previews[node.id])Object.assign(node,previews[node.id]);return result})
watch(()=>root.value?.id,async value=>{if(value){await nextTick();fit()}},{once:true})
const client=crypto.randomUUID(),name=ref('协作者'),connected=ref(false),peers=reactive<Record<string,any>>({}),clock=ref(Date.now()),livePeers=computed(()=>Object.values(peers).filter(p=>clock.value-p.time<30000)),follow=ref(''),activity=ref('')
let removeWs:(()=>void)[]=[],poll:ReturnType<typeof setInterval>|undefined,scrollTimer:ReturnType<typeof setTimeout>|undefined,drag:any=null,wasDragging=false,disposed=false,fetching:Promise<void>|undefined
function normalize(node:any,parentId:string|null=null):MapNode{let style:Record<string,any>={};try{style=JSON.parse(node.styleJson||'{}')}catch{}const result:MapNode={id:String(node.id),content:node.content||'节点',parentId,children:[],style,styleJson:node.styleJson||'{}',icon:node.icon||'',note:node.note||'',link:node.link||'',sortOrder:node.sortOrder||0};result.children=(node.children||[]).map((c:any)=>normalize(c,result.id));return result}
async function load():Promise<void>{if(fetching){await fetching;return}fetching=(async()=>{const r:any=await request.get('/mindmap/'+id);if(disposed)return;title.value=r.data.title;layout.value=r.data.layoutType||'mindmap';root.value=r.data.rootNode?normalize(r.data.rootNode):undefined;if(!selected.value)selectedId.value=root.value?.id||''})();try{await fetching}finally{fetching=undefined}}
function selectNode(node:MapNode){if(wasDragging){wasDragging=false;return}selectedId.value=node.id;broadcastView()}
function nodeStyle(node:MapNode){return {background:node.style.background||(!node.parentId?'var(--c-brand-light)':'var(--c-surface)'),color:node.style.color||'var(--c-text)',borderColor:node.style.borderColor||'var(--c-border)',fontSize:(node.style.fontSize||14)+'px',fontFamily:node.style.fontFamily||'inherit'}}
function connector(node:PlacedNode){const parent=geometry.value.nodes.find(n=>n.id===node.parentId);if(!parent)return '';if(layout.value==='fishbone'&&!parent.parentId)return `M${node.x+92},${node.y<parent.y?node.y+72:node.y} L${node.x+170},${parent.y+36}`;const a=layout.value==='org'?[parent.x+92,parent.y+72]:[parent.x+184,parent.y+36],b=layout.value==='org'?[node.x+92,node.y]:[node.x,node.y+36];if(node.style.connector==='straight')return `M${a} L${b}`;if(node.style.connector==='elbow')return layout.value==='org'?`M${a} V${(a[1]!+b[1]!)/2} H${b[0]} V${b[1]}`:`M${a} H${(a[0]!+b[0]!)/2} V${b[1]} H${b[0]}`;return layout.value==='org'?`M${a} C${a[0]},${a[1]!+40} ${b[0]},${b[1]!-40} ${b}`:`M${a} C${a[0]!+40},${a[1]} ${b[0]!-40},${b[1]} ${b}`}
async function mutate(action:()=>Promise<unknown>,label:string){if(saving.value)return false;saving.value=true;error.value='';try{await action();await load();activity.value=label;wsClient.send('MINDMAP_NODE_UPDATE',{client,name:name.value,label},id);return true}catch(e:any){error.value=e.message||'保存失败';return false}finally{saving.value=false}}
async function prompt(label:string,value=''){return (await ElMessageBox.prompt('内容',label,{inputValue:value,inputValidator:v=>!!v?.trim()&&v.length<=500||'请输入1到500字'})).value.trim()}
async function add(sibling:boolean){if(!canEdit.value||!selected.value)return;try{const content=await prompt(sibling?'添加同级节点':'添加子节点'),parentId=sibling?selected.value.parentId:selected.value.id;await mutate(()=>request.post(`/mindmap/${id}/node`,null,{params:{parentId,content}}),'添加了节点')}catch{}}
let editingSource:MapNode|undefined
function edit(){if(!selected.value)return;editingSource=JSON.parse(JSON.stringify(selected.value));Object.assign(draft,JSON.parse(JSON.stringify(editingSource)));draft.style={color:'#1d2129',background:'#ffffff',borderColor:'#c9d2e1',lineColor:'#a4b5cf',fontSize:14,fontFamily:'Arial',connector:'curve',lineStyle:'solid',tag:'',...draft.style};editOpen.value=true}
function body(node:MapNode,patch:Record<string,any>={}){return {content:node.content,styleJson:JSON.stringify(node.style),note:node.note,link:node.link,icon:node.icon,parentId:node.parentId,expectedParentId:node.parentId,expectedContent:node.content,expectedStyleJson:node.styleJson,expectedNote:node.note,expectedLink:node.link,expectedIcon:node.icon,...patch}}
async function saveDraft(){const source=editingSource;if(!source)return;const ok=await mutate(()=>request.put(`/mindmap/${id}/nodes/${source.id}/properties`,body(source,{content:draft.content,styleJson:JSON.stringify(draft.style),note:draft.note,link:draft.link,icon:draft.icon,parentId:draft.parentId})),'更新了节点属性');if(ok)editOpen.value=false}
async function saveStyle(node:MapNode,style:Record<string,any>,label:string){return mutate(()=>request.put(`/mindmap/${id}/nodes/${node.id}/properties`,body(node,{styleJson:JSON.stringify(style)})),label)}
async function collapse(){const node=selected.value;if(node&&canEdit.value)await saveStyle(node,{...node.style,collapsed:!node.style.collapsed},'调整了节点展开状态')}
async function remove(){if(!canEdit.value||!selected.value?.parentId)return;try{await ElMessageBox.confirm('删除此节点及全部子节点？可通过操作历史恢复。','删除节点',{type:'warning'});const nodeId=selected.value.id;await mutate(()=>request.delete('/mindmap/node/'+nodeId),'删除了节点')}catch{}}
async function saveLayout(){await mutate(()=>request.put(`/mindmap/${id}/layout`,null,{params:{type:layout.value}}),'切换了布局');fit()}
function fit(){zoom.value=Math.max(.25,Math.min(1,(mapScroll.value?.clientWidth||700)/geometry.value.width));if(mapScroll.value){mapScroll.value.scrollTop=0;mapScroll.value.scrollLeft=0}}
function dragStart(event:PointerEvent,node:PlacedNode){selectedId.value=node.id;if(!canEdit.value||saving.value||presenting.value||event.button!==0)return;(event.currentTarget as HTMLElement).setPointerCapture(event.pointerId);drag={id:node.id,startX:event.clientX,startY:event.clientY,x:node.x,y:node.y,source:allNodes.value.find(n=>n.id===node.id)};wasDragging=false}
function dragMove(event:PointerEvent){if(!drag)return;const dx=(event.clientX-drag.startX)/zoom.value,dy=(event.clientY-drag.startY)/zoom.value;if(Math.abs(dx)+Math.abs(dy)>5){wasDragging=true;previews[drag.id]={x:Math.max(16,drag.x+dx),y:Math.max(16,drag.y+dy)}}}
async function dragEnd(){if(!drag)return;const current=drag;drag=null;if(wasDragging&&previews[current.id]){const style={...current.source.style,positions:{...current.source.style.positions,[layout.value]:previews[current.id]}};await saveStyle(current.source,style,'移动了节点位置')}delete previews[current.id]}
function cancelDrag(){if(drag)delete previews[drag.id];drag=null}
function peerAt(nodeId:string){return livePeers.value.some(p=>p.nodeId===nodeId)}
function broadcastView(){if(scrollTimer)clearTimeout(scrollTimer);scrollTimer=setTimeout(()=>{if(connected.value&&!follow.value)wsClient.send('DOC_CURSOR',{kind:'mindmap',client,name:name.value,nodeId:selectedId.value,nodeName:selected.value?.content,zoom:zoom.value,left:mapScroll.value?.scrollLeft||0,top:mapScroll.value?.scrollTop||0},id)},100)}
async function loadPresentation(){const r:any=await request.get(`/mindmap/${id}/presentation/state`);Object.assign(presentation,r.data);if(presenting.value&&presentation.currentNodeId){selectedId.value=String(presentation.currentNodeId);centerNode(selectedId.value)}}
async function control(action:string,extra:Record<string,any>={}){try{const r:any=await request.post(`/mindmap/${id}/presentation/control`,{action,...extra});Object.assign(presentation,r.data);if(action==='start')followPresentation.value=true;wsClient.send('MINDMAP_NODE_UPDATE',{client,kind:'presentation',name:name.value},id);if(presenting.value)centerNode(String(presentation.currentNodeId))}catch(e:any){error.value=e.message}}
async function annotate(){try{const value=await prompt('演示标注',presentation.annotation||'');await control('annotate',{annotation:value})}catch{}}
function centerNode(nodeId:string){const node=geometry.value.nodes.find(n=>n.id===nodeId);if(node&&mapScroll.value){mapScroll.value.scrollLeft=Math.max(0,node.x*zoom.value-mapScroll.value.clientWidth/2+92);mapScroll.value.scrollTop=Math.max(0,node.y*zoom.value-mapScroll.value.clientHeight/2+36)}}
async function openHistory(){try{const r:any=await request.get(`/mindmap/${id}/snapshots`);history.value=r.data;historyOpen.value=true}catch(e:any){error.value=e.message}}
async function restore(snapshotId:number){try{await ElMessageBox.confirm('恢复此操作前的节点状态？当前状态也会保留为快照。','恢复操作');if(await mutate(()=>request.post(`/mindmap/${id}/snapshots/${snapshotId}/rollback`),'恢复了历史节点'))historyOpen.value=false}catch{}}
async function capture(){try{const name=await prompt('模板名称',title.value);await request.post('/template/create',{sourceDocId:id,name,category:'思维导图'});ElMessage.success('模板已保存至模板中心')}catch{}}
function download(blob:Blob,type:string){const url=URL.createObjectURL(blob),link=document.createElement('a');link.href=url;link.download=title.value+'.'+type;link.click();setTimeout(()=>URL.revokeObjectURL(url),10000)}
async function exportMap(){exporting.value=true;try{
  const g=geometry.value,scale=Math.min(2,4096/g.width,4096/g.height),canvas=document.createElement('canvas');canvas.width=Math.ceil(g.width*scale);canvas.height=Math.ceil(g.height*scale);const c=canvas.getContext('2d')!;c.scale(scale,scale);c.fillStyle='#ffffff';c.fillRect(0,0,g.width,g.height)
  if(layout.value==='fishbone'){const y=(g.nodes.find(n=>!n.parentId)?.y||0)+36;c.strokeStyle='#a4b5cf';c.beginPath();c.moveTo(200,y);c.lineTo(g.width-20,y);c.stroke()}
  for(const n of g.nodes.filter(n=>n.parentId)){c.strokeStyle=n.style.lineColor||'#a4b5cf';c.lineWidth=2;c.setLineDash(n.style.lineStyle==='dashed'?[6,4]:[]);c.stroke(new Path2D(connector(n)))}c.setLineDash([])
  for(const n of g.nodes){c.fillStyle=n.style.background||(!n.parentId?'#e9f0ff':'#ffffff');c.strokeStyle=n.style.borderColor||'#c9d2e1';c.fillRect(n.x,n.y,184,72);c.strokeRect(n.x,n.y,184,72);c.fillStyle=n.style.color||'#1d2129';const size=n.style.fontSize||14;c.font=`${size}px ${n.style.fontFamily||'Arial'}`;let line='',row=0;for(const letter of n.content){if(c.measureText(line+letter).width>158){c.fillText(line,n.x+12,n.y+22+row*(size+3));line='';row++;if(row>=2)break}line+=letter}if(row<2)c.fillText(line,n.x+12,n.y+22+row*(size+3));if(n.style.tag){c.font='10px Arial';c.fillText(n.style.tag,n.x+12,n.y+65,150)}if(n.icon||n.note){c.font='10px Arial';c.fillText([n.icon?'★':'',n.note?'•':''].join(' '),n.x+155,n.y+15)}}
  if(exportType.value==='png'){const blob=await new Promise<Blob>((resolve,reject)=>canvas.toBlob(b=>b?resolve(b):reject(new Error('图片生成失败'))));download(blob,'png')}else{const r:any=await request.post(`/mindmap/${id}/export`,{image:canvas.toDataURL('image/png').split(',')[1]},{timeout:60000});download(new Blob([Uint8Array.from(atob(r.data.base64),(s:string)=>s.charCodeAt(0))],{type:'application/pdf'}),'pdf')}exportOpen.value=false
}catch(e:any){if(!e.displayed)ElMessage.error(e.message||'导出失败')}finally{exporting.value=false}}
onMounted(async()=>{loading.value=true;try{const d:any=await request.get('/document/'+id);canEdit.value=d.data.canEdit===true;const u:any=await request.get('/user/info');userId.value=String(u.data.userId);name.value=u.data.nickname||u.data.username;await load();await loadPresentation();wsClient.connect(getToken()||undefined);removeWs.push(wsClient.onStatusChange(ok=>{connected.value=ok;if(ok){wsClient.send('DOC_JOIN',{},id);broadcastView();load().catch(()=>{})}}),wsClient.on('mindmap_node_broadcast',async data=>{if(data.roomId!==id||data.client===client)return;activity.value=(data.name||'协作者')+' '+(data.label||'更新了演示');try{await load();await loadPresentation()}catch(e:any){error.value=e.message}}),wsClient.on('doc_cursor_broadcast',data=>{if(data.roomId!==id||data.kind!=='mindmap'||data.client===client)return;const entering=!peers[data.client]||Date.now()-peers[data.client].time>30000;peers[data.client]={...data,time:Date.now()};if(entering)activity.value=data.name+' 加入了导图';if(follow.value===data.client&&mapScroll.value){zoom.value=data.zoom||1;mapScroll.value.scrollLeft=data.left||0;mapScroll.value.scrollTop=data.top||0;selectedId.value=data.nodeId}}));poll=setInterval(()=>{clock.value=Date.now();for(const peer of Object.values(peers))if(!peer.expired&&clock.value-peer.time>30000){peer.expired=true;activity.value=peer.name+' 离开了导图'}broadcastView();loadPresentation().catch(()=>{});if(!connected.value)load().catch(()=>{})},10000)}catch(e:any){error.value=e.message}finally{loading.value=false}})
onBeforeUnmount(()=>{disposed=true;if(poll)clearInterval(poll);if(scrollTimer)clearTimeout(scrollTimer);removeWs.forEach(fn=>fn());wsClient.send('DOC_LEAVE',{},id)})
</script>
